public static int searchDanmaku(OkHttpClient client, Result result, History history, Episode episode, BooleanSupplier isCurrent, Consumer<Danmaku> set, Consumer<Danmaku> add) {
    if (!isCurrent.getAsBoolean()) return -1;
    DanmakuApi.cancel();
    if (!DanmakuApi.canSearch()) return -1;
    if (VodConfig.get().getSite(result.getKey()).getDanmaku() == 0) return -1;
    return DanmakuApi.search(client, history.getVodName(), episode.getName(), items -> {
        if (!isCurrent.getAsBoolean()) return;
        items.stream().findFirst().ifPresent(danmaku -> {
            if (DanmakuSetting.isSpiderFirst() && !result.getDanmaku().isEmpty()) add.accept(danmaku);
            else set.accept(danmaku);
        });
    }, error -> { }, null);
}

