public void loadDanmaku(Result result, History history, Episode episode) {
        BooleanSupplier current = () -> isNativePlaybackCurrent() && mVod.isCurrentResult(result);
        if (!isBindingOwner() || isXrayStarting() || player().isXrayPlaybackSuspended()) return;
        if (player().hasXraySession() && !current.getAsBoolean()) return;
        DanmakuApi.cancel(mDanmakuRequestId);
        mDanmakuRequestId = -1;
        if (player().hasXraySession()) {
            OkHttpClient fallback = OkHttp.player();
            OkHttpClient client = player().getPlaybackHttpClient(fallback);
            if (client == fallback) return;
            mDanmakuRequestId = VodPlaybackMedia.searchDanmaku(client, result, history, episode, current, player()::setDanmaku, player()::addDanmaku);
        } else {
            VodPlaybackMedia.searchDanmaku(result, history, episode, current, player()::setDanmaku, player()::addDanmaku);
        }
    }

